class Boeing {
  + Name : string
}

class Airline {
  + Name : string
}

class Employee {
  + Name : string
}

class Contract {
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + Model : string
  + Price : double
  + OptionsAndCustomizations : string
  + DeliveryDate : date
}

Boeing "1" -- "*" Contract : manages
Boeing "1" -- "*" Employee : employs
Boeing "1" -- "*" Acquisition : builds
Contract "1" -- "1..*" Acquisition : consists of
Contract "1" -- "1" Employee : managed by
Airline "0..1" -- "0..*" Airline : is parent of
Airline "1" -- "0..*" Contract : signs
Acquisition "1" -- "1" Airline : sold to

@enduml

